    @staticmethod
    def _require_current_slice_path_scope(
        current: Mapping[str, Any],
        *,
        project_dir: str | Path,
    ) -> None:
        """Check every prepared repository against the same overall slice."""
        entries = current["data"].get("repository_deliveries") or []
        for entry in entries or [{"repository_id": current["data"].get("selected_repository_id"), "git": current["data"].get("git") or {}}]:
            if ((entry.get("git") or {}).get("cleanup") or {}).get("safe"):
                continue
            root = ApplicationCoordinator._execution_root_for_area(entry.get("git") or {}, project_dir)
            ApplicationCoordinator._require_repository_slice_path_scope(repository_item(current, entry["repository_id"]), project_dir=root)

    @staticmethod
    def _require_repository_slice_path_scope(current: Mapping[str, Any], *, project_dir: str | Path) -> None:

        if current.get("status") != "implementing":
            return
        data = current.get("data")
        engineering = (
            data.get("engineering") if isinstance(data, Mapping) else None
        )
        plan = (
            engineering.get("plan")
            if isinstance(engineering, Mapping)
            else None
        )
        if not isinstance(plan, Mapping) or not plan.get(
            "implementation_slices"
        ):
            return
        receipts = data.get("verifications") if isinstance(data, Mapping) else []
        completions = (
            data.get("implementation_slice_completions")
            if isinstance(data, Mapping)
            else []
        )
        current_slice = focused_slice(
            plan,
            receipts if isinstance(receipts, list) else [],
            completions if isinstance(completions, list) else [],
        )
        if isinstance(current_slice, Mapping) and current_slice.get(
            "continued_operation_refs"
        ):
            assessment = engineering.get("assessment")
            investigation_ref = (
                str(assessment.get("investigation_ref") or "")
                if isinstance(assessment, Mapping)
                else ""
            )
            checker = ProjectAuthorityConsistency(project_dir)
            try:
                candidate = checker.load_working_tree_candidate_for(
                    investigation_ref
                )
                alignment_paths = set(
                    checker.authority_governed_paths(
                        candidate,
                        "implementation_alignment",
                    )
                )
            except ProjectAuthorityConsistencyError as error:
                raise VerificationRunnerError(
                    "implementation_alignment_refresh_scope_invalid",
                    "实现对齐延续刷新前无法复核完整候选权威路径",
                    details=error.issues,
                ) from error
            continued_paths = set(
                ApplicationCoordinator._slice_operation_paths(
                    plan,
                    {
                        **dict(current_slice),
                        "operation_refs": [],
                    },
                )
            )
            outside_alignment = sorted(continued_paths - alignment_paths)
            if outside_alignment:
                raise VerificationRunnerError(
                    "implementation_alignment_refresh_scope_invalid",
                    "延续操作包含不属于当前实现对齐候选的治理路径",
                    details={
                        "slice_id": current_slice.get("slice_id"),
                        "outside_alignment_paths": outside_alignment,
                    },
                )
        ApplicationCoordinator._require_completed_slice_snapshots(
            current,
            project_dir=project_dir,
        )
        scope = permitted_slice_operation_paths(
            plan,
            receipts if isinstance(receipts, list) else [],
            completions if isinstance(completions, list) else [],
            repository_id=current["data"].get("selected_repository_id"),
        )
        work_area = ApplicationCoordinator._work_area(current)
        actual_paths = set(
            ApplicationCoordinator._repository_changed_paths(current)
        )
        permitted_paths = set(scope["permitted_paths"])
        planned_paths = set(scope["planned_paths"])
        future_paths = set(scope["future_paths"])
        preauthored_governance_paths: set[str] = set()
        all_authority_kinds = planned_upstream_authority_kinds(
            current,
            current_progress_only=False,
        )
        if all_authority_kinds:
            ApplicationCoordinator._require_upstream_authority_decisions(
                current,
                {"changed_authority_kinds": all_authority_kinds},
                project_dir=project_dir,
            )
            try:
                preauthored_governance_paths.update(
                    planned_project_authority_paths(project_dir, current)
                )
            except ProjectAuthorityDecisionError as error:
                raise VerificationRunnerError(
                    error.code,
                    str(error),
                    details=error.details,
                ) from error
        premature_paths = sorted(
            actual_paths & (future_paths - preauthored_governance_paths)
        )
        if premature_paths:
            raise VerificationRunnerError(
                "implementation_slice_path_not_ready",
                "工作树包含只属于后续实施切片的文件；请恢复提前改动，"
                "或在确需调整顺序时先重新规划",
                details={
                    "current_slice_id": scope["current_slice_id"],
                    "permitted_paths": sorted(permitted_paths),
                    "premature_paths": premature_paths,
                },
            )
        unplanned_paths = sorted(actual_paths - planned_paths)
        if unplanned_paths:
            raise VerificationRunnerError(
                "unplanned_repository_change",
                "工作树包含未归属于任何已确认工程操作的路径；验证副产物或误改应精确清理，"
                "必要的持久改动必须先重新规划",
                details={
                    "current_slice_id": scope["current_slice_id"],
                    "unplanned_paths": unplanned_paths,
                },
            )


__all__ = [
    "ApplicationCoordinator",
    "ApplicationCoordinatorError",
]

strixnova/src/strixnova/behavior_example.text:
"""Direction-owned examples; identity and coverage, never business interpretation."""

from __future__ import annotations

from collections.abc import Mapping
from copy import deepcopy
import hashlib
import json
import re
from typing import Any


DIRECTION_SCHEMA = "strixnova.direction-decision.v1"
EXAMPLE_ID = re.compile(r"DIREX-[0-9A-F]{16}")
MAX_EXAMPLES = 256




class BehaviorExampleError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


def _fail(message: str, code: str = "behavior_example_invalid") -> None:
    raise BehaviorExampleError(code, message)


def _text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value.strip() or len(value) > 16000:
        _fail(f"{field} 必须是非空且有界的文本")
    return value.strip()


def _texts(value: Any, field: str) -> list[str]:
    if not isinstance(value, list) or not value or len(value) > 64:
        _fail(f"{field} 必须是非空且有界的数组")
    result = [_text(item, field) for item in value]
    if len(set(result)) != len(result):
        _fail(f"{field} 不得重复")
    return result


def normalize_behavior(value: Any, *, allow_undetermined: bool = False) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        _fail("每项验收必须明确 behavior 例子或不适用理由")
    applicability = value.get("applicability")
    if not isinstance(applicability, str):
        _fail("behavior.applicability 必须是文本枚举")
    if applicability in {"not_applicable", "undetermined"}:
        if set(value) != {"applicability", "reason"}:
            _fail("不适用或未决的 behavior 只能包含 applicability 和 reason")
        if applicability == "undetermined" and not allow_undetermined:
            _fail("行为例子适用性尚未确定，方向不能进入确认", "behavior_examples_undetermined")
        return {"applicability": applicability, "reason": _text(value["reason"], "behavior.reason")}
    if applicability != "required" or set(value) != {"applicability", "examples"}:
        _fail("behavior 必须明确 required、not_applicable 或 undetermined")
    raw_examples = value["examples"]
    if not isinstance(raw_examples, list) or not raw_examples or len(raw_examples) > MAX_EXAMPLES:
        _fail("required 的 behavior 必须有 1 至 256 个具体例子")
    result = []
    seen: set[str] = set()
    for raw in raw_examples:
        if not isinstance(raw, Mapping) or set(raw) != {"example_id", "title", "given", "when", "then", "basis_refs"}:
            _fail("例子必须且只能包含 example_id、title、given、when、then、basis_refs")
        identifier = raw["example_id"]
        if not isinstance(identifier, str) or not EXAMPLE_ID.fullmatch(identifier):
            _fail("example_id 必须为 DIREX- 加十六位大写十六进制字符")
        if identifier in seen:
            _fail(f"行为例子身份重复：{identifier}", "behavior_example_duplicate")
        seen.add(identifier)
        result.append({
            "example_id": identifier,
            "title": _text(raw["title"], "example.title"),
            "given": _texts(raw["given"], "example.given"),
            "when": _text(raw["when"], "example.when"),
            "then": _texts(raw["then"], "example.then"),
            "basis_refs": _texts(raw["basis_refs"], "example.basis_refs"),
        })
    return {"applicability": "required", "examples": result}


def example_catalog(direction: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    """Return exact examples and their parent/basis from the current direction contract."""
    if direction.get("schema_version") != DIRECTION_SCHEMA:
        _fail("行为例子需要当前完整方向合同", "direction_contract_invalid")
    requirements = {
        f"direction.requirement:{item['requirement_id']}": item["statement"]
        for item in direction.get("scope", [])
    }
    constraints = {
        f"direction.constraint:{item['constraint_id']}": item["statement"]
        for item in direction.get("constraints", [])
    }
    result: dict[str, dict[str, Any]] = {}
    for acceptance in direction.get("acceptance", []):
        behavior = normalize_behavior(acceptance.get("behavior"))
        if behavior["applicability"] != "required":
            continue
        parent = f"direction.acceptance:{acceptance['acceptance_id']}"
        allowed = {
            f"direction.requirement:{identifier}"
            for identifier in acceptance["requirement_refs"]
        } | set(constraints)
        for example in behavior["examples"]:
            reference = f"direction.example:{example['example_id']}"
            if reference in result:
                _fail(f"行为例子身份跨验收重复：{example['example_id']}", "behavior_example_duplicate")
            unknown = set(example["basis_refs"]) - allowed
            if unknown:
                _fail("例子预期依据必须引用本验收的需求或当前约束：" + ", ".join(sorted(unknown)), "behavior_example_basis_unknown")
            basis = {ref: {**requirements, **constraints}[ref] for ref in example["basis_refs"]}
            binding = {"parent_acceptance_ref": parent, "acceptance_statement": acceptance["statement"], "example": example, "basis": basis}
            fingerprint = hashlib.sha256(json.dumps(binding, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
            result[reference] = {"target_ref": reference, "parent_acceptance_ref": parent, **deepcopy(example), "example_sha256": fingerprint}
    if len(result) > MAX_EXAMPLES:
        _fail("同一方向最多包含 256 个行为例子")
    return result


def example_ids(direction: Mapping[str, Any]) -> set[str]:
    identifiers: set[str] = set()
    for acceptance in direction.get("acceptance") or []:
        behavior = acceptance.get("behavior") if isinstance(acceptance, Mapping) else None
        if not isinstance(behavior, Mapping) or not isinstance(behavior.get("examples"), list):
            continue
        identifiers.update(
            example["example_id"] for example in behavior["examples"]
            if isinstance(example, Mapping) and isinstance(example.get("example_id"), str)
        )
    return identifiers


def example_parents(examples: Mapping[str, Mapping[str, Any]]) -> dict[str, list[str]]:
    parents: dict[str, list[str]] = {}
    for reference, example in examples.items():
        parents.setdefault(str(example["parent_acceptance_ref"]), []).append(reference)
    return {parent: sorted(children) for parent, children in parents.items()}

strixnova/src/strixnova/confirmation_pro.text:
"""Deterministic candidate binding for the three user confirmation gates.

The protocol deliberately does not decide whether a candidate is good or
whether an explanation was understood. The Agent interprets the user's later
message; the program binds that explicit interpretation and verbatim message
to one candidate and WorkItem version.
"""

from __future__ import annotations

from collections.abc import Mapping
import hashlib
import json
from typing import Any


CONFIRMATION_CHALLENGE_SCHEMA = "strixnova.confirmation-challenge.v1"
USER_CONFIRMATION_SCHEMA = "strixnova.user-confirmation.v1"

_CONFIRMATION_SPECS = {
    "confirm_direction": ("direction", "当前展示的方向"),
    "confirm_engineering_plan": (
        "engineering_plan",
        "当前展示的工程方案",
    ),
    "confirm_actual_result": ("actual_result", "当前展示的实际结果"),
}

class ConfirmationProtocolError(ValueError):
    """One confirmation challenge or reply is structurally invalid."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


def _required_text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ConfirmationProtocolError(
            "confirmation_input_invalid",
            f"{field} 必须是非空字符串",
        )
    return value.strip()


def _candidate_for(
    action_type: str,
    data: Mapping[str, Any],
) -> Mapping[str, Any]:
    if action_type == "confirm_direction":
        candidate = data.get("direction")
    elif action_type == "confirm_engineering_plan":
        engineering = data.get("engineering")
        candidate = (
            engineering.get("plan")
            if isinstance(engineering, Mapping)
            else None
        )
    elif action_type == "confirm_actual_result":
        candidate = data.get("actual_result")
    else:
        raise ConfirmationProtocolError(
            "confirmation_action_invalid",
            f"当前动作不是用户确认：{action_type or '<empty>'}",
        )
    if not isinstance(candidate, Mapping):
        raise ConfirmationProtocolError(
            "confirmation_candidate_missing",
            "当前确认动作缺少完整候选记录",
        )
    return candidate


def confirmation_challenge_for(
    *,
    action_type: str,
    work_item_id: str,
    work_item_version: int,
    data: Mapping[str, Any],
) -> dict[str, Any]:
    """Project one stable challenge from exact stored candidate identity."""

    spec = _CONFIRMATION_SPECS.get(action_type)
    if spec is None:
        raise ConfirmationProtocolError(
            "confirmation_action_invalid",
            f"当前动作不是用户确认：{action_type or '<empty>'}",
        )
    identifier = _required_text(work_item_id, "work_item_id")
    if type(work_item_version) is not int or work_item_version < 1:
        raise ConfirmationProtocolError(
            "confirmation_version_invalid",
            "work_item_version 必须是正整数",
        )
    candidate_kind, decision_label = spec
    candidate = _candidate_for(action_type, data)
    envelope = {
        "schema_version": CONFIRMATION_CHALLENGE_SCHEMA,
        "work_item_id": identifier,
        "work_item_version": work_item_version,
        "action_type": action_type,
        "candidate": candidate,
    }
    try:
        canonical = json.dumps(
            envelope,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError) as error:
        raise ConfirmationProtocolError(
            "confirmation_candidate_invalid",
            "当前候选无法形成稳定身份指纹",
        ) from error
    digest = hashlib.sha256(canonical).hexdigest()
    return {
        "schema_version": CONFIRMATION_CHALLENGE_SCHEMA,
        "candidate_kind": candidate_kind,
        "candidate_fingerprint": f"sha256:{digest}",
        "decision_label": decision_label,
        "decision_interpreter": "coding_agent",
    }


def confirmation_input_schema(
    challenge: Mapping[str, Any],
) -> dict[str, Any]:
    """Return the exact public payload schema for one challenge."""

    fingerprint = _required_text(
        challenge.get("candidate_fingerprint"),
        "candidate_fingerprint",
    )
    common = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "type": "object",
        "additionalProperties": False,
        "required": ["candidate_fingerprint", "user_confirmation", "agent_decision"],
        "properties": {
            "candidate_fingerprint": {"const": fingerprint},
            "user_confirmation": {"type": "string", "pattern": r"\S"},
        },
    }
    branches = []
    for decision in ("accept", "request_changes"):
        branches.append({
            **common,
            "properties": {
                **common["properties"],
                "agent_decision": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["decision", "reason"],
                    "properties": {
                        "decision": {"const": decision},
                        "reason": {"type": "string", "pattern": r"\S"},
                    },
                },
            },
        })
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "strixnova.user-confirmation-input.v1",
        "oneOf": branches,
    }




def confirmation_record_from_input(
    challenge: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    """Validate bindings and record Agent interpretation, without reading intent."""

    if not isinstance(payload, Mapping) or set(payload) != {
        "candidate_fingerprint", "user_confirmation", "agent_decision"
    }:
        raise ConfirmationProtocolError(
            "confirmation_input_invalid",
            "确认输入必须包含 candidate_fingerprint、用户原话 user_confirmation 和 agent_decision",
        )
    fingerprint = _required_text(challenge.get("candidate_fingerprint"), "candidate_fingerprint")
    if _required_text(payload.get("candidate_fingerprint"), "candidate_fingerprint") != fingerprint:
        raise ConfirmationProtocolError(
            "confirmation_candidate_mismatch", "当前输入不属于已展示的精确候选",
        )
    message = payload.get("user_confirmation")
    _required_text(message, "user_confirmation")
    interpretation = payload.get("agent_decision")
    if not isinstance(interpretation, Mapping) or set(interpretation) != {"decision", "reason"}:
        raise ConfirmationProtocolError(
            "confirmation_input_invalid", "agent_decision 必须包含 decision 和 reason",
        )
    decision = interpretation.get("decision")
    if decision not in ("accept", "request_changes"):
        raise ConfirmationProtocolError(
            "confirmation_input_invalid", "未明确的答复不得提交确认；应先解释或澄清",
        )
    reason = _required_text(interpretation.get("reason"), "agent_decision.reason")
    return {
        "schema_version": USER_CONFIRMATION_SCHEMA,
        "accepted": decision == "accept",
        "candidate_kind": _required_text(challenge.get("candidate_kind"), "candidate_kind"),
        "candidate_fingerprint": fingerprint,
        "decision_label": _required_text(challenge.get("decision_label"), "decision_label"),
        "user_confirmation": message,
        "summary": reason,
        "agent_decision": {"decision": decision, "reason": reason},
        "decision_interpreter": "coding_agent",
        "semantic_content_machine_proven": False,
    }


def reproduce_confirmation_record(
    challenge: Mapping[str, Any], record: Mapping[str, Any],
) -> dict[str, Any]:
    """Recheck persisted decisions using their recorded interpretation contract."""

    payload = {key: record.get(key) for key in ("candidate_fingerprint", "user_confirmation")}
    if record.get("schema_version") == USER_CONFIRMATION_SCHEMA:
        payload["agent_decision"] = record.get("agent_decision")
        return confirmation_record_from_input(challenge, payload)
    raise ConfirmationProtocolError(
        "confirmation_input_invalid", "不支持该确认记录版本",
    )


__all__ = [
    "CONFIRMATION_CHALLENGE_SCHEMA",
    "USER_CONFIRMATION_SCHEMA",
    "ConfirmationProtocolError",
    "confirmation_challenge_for",
    "confirmation_input_schema",
    "confirmation_record_from_input",
    "reproduce_confirmation_record",
]

