      "type": "object",
      "additionalProperties": false,
      "required": [
        "role",
        "path",
        "sha256",
        "command_argument_index"
      ],
      "properties": {
        "role": {
          "enum": [
            "executable",
            "entry_script",
            "config",
            "supporting_file"
          ]
        },
        "path": {
          "type": "string",
          "minLength": 1
        },
        "sha256": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "command_argument_index": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        }
      }
    },
    "external_observation_process_policy": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "policy_id",
        "purpose",
        "forbidden_program_names"
      ],
      "properties": {
        "policy_id": {
          "type": "string",
          "pattern": "^PROCESSPOLICY-[0-9A-F]{16}$"
        },
        "purpose": {
          "type": "string",
          "minLength": 1
        },
        "forbidden_program_names": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "external_observation_limits": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "timeout_seconds",
        "cleanup_timeout_seconds",
        "max_input_bytes",
        "max_output_bytes"
      ],
      "properties": {
        "timeout_seconds": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 3600
        },
        "cleanup_timeout_seconds": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 300
        },
        "max_input_bytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 67108864
        },
        "max_output_bytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 268435456
        }
      }
    },
    "delivery_plan": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "expected_outcome",
        "rollback_or_recovery",
        "limitations",
        "evidence_refs"
      ],
      "properties": {
        "expected_outcome": {
          "type": "string",
          "minLength": 1
        },
        "rollback_or_recovery": {
          "type": "string",
          "minLength": 1
        },
        "limitations": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "evidence_refs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "repository_order": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": [
              "string",
              "null"
            ],
            "pattern": "^REPO-[0-9A-F]{16}$"
          }
        }
      }
    },
    "unknown_or_limitation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "statement",
        "impact",
        "handling",
        "evidence_refs"
      ],
      "properties": {
        "statement": {
          "type": "string",
          "minLength": 1
        },
        "impact": {
          "type": "string",
          "minLength": 1
        },
        "handling": {
          "type": "string",
          "minLength": 1
        },
        "evidence_refs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "requested_assurance": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "band",
        "reason"
      ],
      "properties": {
        "band": {
          "enum": [
            "A0",
            "A1",
            "A2",
            "A3",
            "A4"
          ]
        },
        "reason": {
          "type": "string",
          "minLength": 1
        }
      }
    }
  }
}

