    },
    "policy_ref": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "path",
        "policy_id",
        "revision_id"
      ],
      "properties": {
        "path": {
          "$ref": "#/$defs/path"
        },
        "policy_id": {
          "type": "string",
          "pattern": "^POLICY-[0-9A-F]{16}$"
        },
        "repository_id": {
          "type": "string",
          "pattern": "^REPO-[0-9A-F]{16}$"
        },
        "ref": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^(?:[0-9a-f]{40}|[0-9a-f]{64})$"
        },
        "revision_id": {
          "type": "string",
          "pattern": "^POLICYREV-[0-9A-F]{16}$"
