strixnova/src/strixnova/resources/semant.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "strixnova.semantic-review.v1",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "review_id",
    "reviewed_refs",
    "checks",
    "findings",
    "question_budget",
    "semantic_content_machine_proven"
  ],
  "properties": {
    "schema_version": {
      "const": "strixnova.semantic-review.v1"
    },
    "review_id": {
      "type": "string",
      "pattern": "^SEMREVIEW-[0-9A-F]{16}$"
    },
    "reviewed_refs": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "checks": {
      "type": "array",
      "minItems": 8,
      "maxItems": 8,
      "items": {
        "$ref": "#/$defs/check"
      }
    },
    "findings": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/finding"
      }
    },
    "question_budget": {
      "$ref": "#/$defs/question_budget"
    },
    "semantic_content_machine_proven": {
      "const": false
    }
  },
  "$defs": {
    "perspective": {
      "enum": [
        "product_to_domain_coverage",
        "terminology_authority_rules_invariants",
        "domain_to_architecture_disposition",
        "plan_and_slice_coverage",
        "orphan_and_authority_inversion",
        "scenario_coverage",
        "nonfunctional_and_risk_coverage",
        "evidence_and_claim_boundaries"
      ]
    },
    "check": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "perspective",
        "status",
        "summary",
        "evidence_refs",
        "finding_ids"
      ],
      "properties": {
        "perspective": {
          "$ref": "#/$defs/perspective"
        },
        "status": {
          "enum": [
            "aligned",
            "finding",
            "not_applicable"
          ]
        },
        "summary": {
          "type": "string",
          "minLength": 1
        },
        "evidence_refs": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "finding_ids": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "pattern": "^FINDING-[0-9]{3,}$"
          }
        }
      }
    },
    "finding": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "finding_id",
        "perspective",
        "severity",
        "status",
        "locations",
        "statement",
        "impact",
        "recommendation",
        "owner_decision_required",
        "decision_refs",
        "resolution"
      ],
      "properties": {
        "finding_id": {
          "type": "string",
          "pattern": "^FINDING-[0-9]{3,}$"
        },
        "perspective": {
          "$ref": "#/$defs/perspective"
        },
        "severity": {
          "enum": [
            "low",
            "medium",
            "high",
            "critical"
          ]
        },
        "status": {
          "enum": [
            "open",
            "resolved",
            "accepted_risk"
          ]
        },
        "locations": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "statement": {
          "type": "string",
          "minLength": 1
        },
        "impact": {
          "type": "string",
          "minLength": 1
        },
        "recommendation": {
          "type": "string",
          "minLength": 1
        },
        "owner_decision_required": {
          "type": "boolean"
        },
        "decision_refs": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "resolution": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1
        }
      }
    },
    "question_budget": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "maximum_questions",
        "questions_asked",
        "resolved_decision_refs",
        "remaining_high_impact_decisions"
      ],
      "properties": {
        "maximum_questions": {
          "const": 5
        },
        "questions_asked": {
          "type": "integer",
          "minimum": 0,
          "maximum": 5
        },
        "resolved_decision_refs": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "remaining_high_impact_decisions": {
          "type": "array",
          "maxItems": 0,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    }
  }
}

strixnova/src/strixnova/resources/verifi.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "strixnova.verification-targets.v1",
  "type": "array",
  "items": {
    "$ref": "#/$defs/target"
  },
  "$defs": {
    "target": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "target_ref",
        "method",
        "reason",
        "evidence_refs",
        "command_ids"
      ],
      "properties": {
        "target_ref": {
          "type": "string",
          "minLength": 1
        },
        "method": {
          "enum": [
            "command",
            "agent_review",
            "existing_evidence",
            "not_verified",
            "examples"
          ]
        },
        "reason": {
          "type": "string",
          "minLength": 1
        },
        "evidence_refs": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "command_ids": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "example": {
          "$ref": "behavior-example-v1.schema.json#/$defs/catalog_entry"
        },
        "case_bindings": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "command_id",
              "test_ids"
            ],
            "properties": {
              "command_id": {
                "type": "string",
                "minLength": 1,
                "maxLength": 16000
              },
              "test_ids": {
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 16000
                },
                "minItems": 1,
                "maxItems": 256
              }
            }
          },
          "minItems": 1
        },
        "child_example_refs": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^direction\\.example:DIREX-[0-9A-F]{16}$"
          },
          "minItems": 1,
          "maxItems": 256
        },
        "assertion_review_required": {
          "const": true
        }
      }
    },
    "review": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "target_ref",
        "method",
        "reason",
        "evidence_refs"
      ],
      "properties": {
        "target_ref": {
          "type": "string",
          "minLength": 1
        },
        "method": {
          "enum": [
            "agent_review",
            "existing_evidence",
            "not_verified"
          ]
        },
        "reason": {
          "type": "string",
          "minLength": 1
        },
        "evidence_refs": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "review_result": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "target_ref",
        "outcome",
        "rationale",
        "evidence_refs"
      ],
      "properties": {
        "target_ref": {
          "type": "string",
          "minLength": 1
        },
        "outcome": {
          "enum": [
            "supported",
            "not_supported",
            "not_verified"
          ]
        },
        "rationale": {
          "type": "string",
          "minLength": 1
        },
        "evidence_refs": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    }
  }
}

strixnova/src/strixnova/resources/work-i.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "strixnova.work-item.v1",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "work_item_id",
    "title",
    "status",
    "version",
    "data",
    "created_at",
    "updated_at"
  ],
  "properties": {
    "schema_version": {
      "const": "strixnova.work-item.v1"
    },
    "work_item_id": {
      "type": "string",
      "minLength": 1
    },
    "title": {
      "type": "string",
      "minLength": 1
    },
    "status": {
      "enum": [
        "discussion",
        "awaiting_direction_confirmation",
        "needs_engineering_assessment",
        "awaiting_plan_confirmation",
        "implementation_ready",
        "exploring",
        "implementing",
        "awaiting_actual_result",
        "commit_required",
        "integration_required",
        "integration_conflict",
        "cleanup_required",
        "replanning_required",
        "cancelled_changes_pending",
        "cancelled",
        "completed"
      ]
    },
    "version": {
      "type": "integer",
      "minimum": 1
    },
    "data": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "raw_request",
        "direction",
        "direction_confirmation",
        "direction_item_history",
        "engineering",
        "verifications",
        "implementation_slice_completions",
        "project_authority_presentations",
        "project_authority_reviews",
        "project_authority_decisions",
        "actual_result",
        "actual_result_confirmation",
        "authority_adoption",
        "cancellation",
        "pending_effect",
        "blockers"
      ],
      "properties": {
        "raw_request": {
          "type": "string",
          "minLength": 1
        },
        "direction": {
          "anyOf": [
            {
              "$ref": "direction-decision-v1.schema.json"
            },
            {
              "type": "null"
            },
            {
              "type": "object",
              "description": "当前讨论中的不完整方向；进入确认前由方向合同完成校验。",
              "properties": {
                "schema_version": {
                  "const": "strixnova.direction-decision.v1"
                }
              }
            }
          ]
        },
        "direction_confirmation": {
          "type": [
            "object",
            "null"
          ]
        },
        "direction_item_history": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "active_ids",
            "retired_ids"
          ],
          "properties": {
            "active_ids": {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "type": "string",
                "pattern": "^DIR(REQ|CON|ACC|EX)-[0-9A-F]{16}$"
              }
            },
            "retired_ids": {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "type": "string",
                "pattern": "^DIR(REQ|CON|ACC|EX)-[0-9A-F]{16}$"
              }
            }
          }
        },
        "engineering": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "assessment",
            "plan",
            "plan_confirmation"
          ],
          "properties": {
            "assessment": {
              "oneOf": [
                {
                  "$ref": "engineering-assessment-v1.schema.json"
                },
                {
                  "type": "null"
                }
              ]
            },
            "plan": {
              "oneOf": [
                {
                  "$ref": "engineering-plan-v1.schema.json"
                },
                {
                  "type": "null"
                }
              ]
            },
            "plan_confirmation": {
              "type": [
                "object",
                "null"
              ]
            }
          }
        },
        "git": {
          "type": "object"
        },
        "verifications": {
          "type": "array"
        },
        "implementation_slice_completions": {
          "type": "array",
          "items": {
            "type": "object"
          }
        },
        "project_authority_presentations": {
          "type": "array",
          "items": {
            "type": "object"
          }
        },
        "project_authority_reviews": {
          "type": "array",
          "items": {
            "type": "object"
          }
        },
        "project_authority_decisions": {
          "type": "array",
          "items": {
            "type": "object"
          }
        },
        "actual_result": {
          "type": [
            "object",
            "null"
          ]
        },
        "actual_result_confirmation": {
          "type": [
            "object",
            "null"
          ]
        },
        "authority_adoption": {
          "type": [
            "object",
            "null"
          ]
        },
        "cancellation": {
          "type": [
            "object",
            "null"
          ]
        },
        "pending_effect": {
          "type": [
            "object",
            "null"
          ]
        },
        "blockers": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "project_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^PROJECT-[0-9A-F]{16}$"
        },
        "repository_deliveries": {
          "type": "array",
          "items": {
            "$ref": "repository-delivery-responsibility-v1.schema.json"
          }
        },
        "selected_repository_id": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "anyOf": [
        {
          "required": [
            "git"
          ]
        },
        {
          "required": [
            "repository_deliveries"
          ]
        }
      ]
    },
    "created_at": {
      "type": "string",
      "minLength": 1
    },
    "updated_at": {
      "type": "string",
      "minLength": 1
    },
    "current_action": {
      "oneOf": [
        {
          "$ref": "current-action-v1.schema.json"
        },
        {
          "type": "null"
        }
      ]
    }
  }
}

