"""Per-target verification arrangements and explicitly attributed results.

Command coverage is derived from the existing command list. Only the targets
that use Agent review, prior evidence or an explicit exception need more input.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from copy import deepcopy
from typing import Any

from strixnova.behavior_examples import example_parents

class VerificationTargetError(ValueError):
    def __init__(self, code: str, message: str, *, details: Any = None) -> None:
        super().__init__(message)
        self.code, self.details = code, details


def _fail(message: str, *, code: str = "verification_target_invalid", details: Any = None) -> None:
    raise VerificationTargetError(code, message, details=details)


def _text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value.strip():
        _fail(f"{field} 必须是非空文本")
    return value.strip()


def _refs(value: Any, field: str) -> list[str]:
    if not isinstance(value, list):
        _fail(f"{field} 必须是引用数组")
    result = [_text(item, field) for item in value]
    if len(result) != len(set(result)):
        _fail(f"{field} 引用重复")
    return result


def validate_reviews(
    value: Any, *, targets: set[str], commands: Sequence[Mapping[str, Any]],
    known_evidence: set[str],
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        _fail("verification_reviews 必须是数组")
    covered = {ref for command in commands for ref in command["covers"]}
    result, seen = [], set()
    for raw in value:
        if not isinstance(raw, Mapping) or set(raw) != {"target_ref", "method", "reason", "evidence_refs"}:
            _fail("核验安排必须包含 target_ref、method、reason、evidence_refs")
        target = _text(raw["target_ref"], "target_ref")
        if target not in targets or target in seen or target in covered:
            _fail("核验目标未知、重复或已经由命令覆盖", details=target)
        method = _text(raw["method"], "method")
        if method not in {"agent_review", "existing_evidence", "not_verified"}:
            _fail("核验方式只允许 agent_review、existing_evidence、not_verified")
        evidence = _refs(raw["evidence_refs"], "evidence_refs")
        if set(evidence) - known_evidence or (method != "not_verified" and not evidence):
            _fail("审阅或证据复用必须引用本轮已知依据", details=target)
        seen.add(target)
        result.append({"target_ref": target, "method": method, "reason": _text(raw["reason"], "reason"), "evidence_refs": evidence})
    missing = sorted(targets - covered - seen)
    if missing:
        _fail("以下验收、约束或风险尚无核验安排或明确处置", code="verification_targets_uncovered", details=missing)
    return result


def compile_targets(
    commands: Sequence[Mapping[str, Any]], reviews: Sequence[Mapping[str, Any]],
    *, examples: Mapping[str, Mapping[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    examples = examples or {}
    entries = {item["target_ref"]: {**item, "command_ids": []} for item in reviews}
    for command in commands:
        for target in command["covers"]:
            entry = entries.setdefault(target, {"target_ref": target, "method": "command", "command_ids": [], "evidence_refs": [], "reason": "使用已确认命令的覆盖声明与实际回执；声明不证明测试充分。"})
            entry["command_ids"].append(command["command_id"])
    for ref, example in examples.items():
        if ref not in entries:
            _fail("行为例子缺少已校验核验安排", details=ref)
        entries[ref]["example"] = deepcopy(dict(example))
        if entries[ref]["method"] == "command":
            entries[ref]["assertion_review_required"] = True
            entries[ref]["case_bindings"] = [
                {"command_id": command["command_id"], "test_ids": list(binding["test_ids"])}
                for command in commands
                for binding in command.get("case_report", {}).get("bindings", [])
                if binding["example_ref"] == ref
            ]
    for parent, children in example_parents(examples).items():
        entries[parent] = {
            "target_ref": parent, "method": "examples", "reason": "验收结果由所属例子的实际证据与 Agent 审阅派生。",
            "evidence_refs": [], "command_ids": [], "child_example_refs": children,
        }
    return [entries[key] for key in sorted(entries)]


def assess_targets(
    plan_targets: Sequence[Mapping[str, Any]] | None, value: Any,
    *, coverage: Mapping[str, Any], known_evidence: set[str], limitations: Sequence[str],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    if not isinstance(value, list):
        _fail("verification_review_results 必须是数组")
    if plan_targets is None:
        _fail("当前工程方案缺少逐项核验目标，不能形成结果", code="verification_targets_missing")
    expected = {item["target_ref"]: item for item in plan_targets if item["method"] not in {"command", "examples"} or item.get("example")}
    submitted = {}
    for raw in value:
        if not isinstance(raw, Mapping) or set(raw) != {"target_ref", "outcome", "rationale", "evidence_refs"}:
            _fail("核验结果必须包含 target_ref、outcome、rationale、evidence_refs")
        target = _text(raw["target_ref"], "target_ref")
        if target not in expected or target in submitted:
            _fail("审阅结果引用未计划或重复的核验目标", details=target)
        plan = expected[target]
        outcome = _text(raw["outcome"], "outcome")
        if outcome not in {"supported", "not_supported", "not_verified"}:
            _fail("审阅结果 outcome 无效")
        if plan["method"] == "not_verified" and outcome != "not_verified":
            _fail("明确不核验的计划不能直接宣称已获支持；请先修订核验安排")
        evidence = _refs(raw["evidence_refs"], "evidence_refs")
        if set(evidence) - (known_evidence | set(plan["evidence_refs"])):
            _fail("核验结果引用未知证据", details=target)
        if outcome != "not_verified" and not evidence:
            _fail("审阅结论必须有明确依据", details=target)
        if outcome != "supported" and not limitations:
            _fail("未核验或不获支持的目标必须保留实际结果限制", details=target)
        submitted[target] = {"target_ref": target, "outcome": outcome, "rationale": _text(raw["rationale"], "rationale"), "evidence_refs": evidence}
    if set(expected) != set(submitted):
        _fail("实际结果缺少已计划的逐项审阅或未核验说明", code="verification_target_results_missing", details=sorted(set(expected) - set(submitted)))
    rows = []
    for plan in plan_targets:
        target = plan["target_ref"]
        if plan["method"] == "examples":
            continue
        if plan["method"] == "command":
            commands = plan["command_ids"]
            results = [coverage.get("results", {}).get(command) for command in commands]
            status = "command_evidence_passed" if results and all(result == "passed" for result in results) else "command_evidence_incomplete"
            row = {"target_ref": target, "method": "command", "status": status, "evidence_refs": [coverage["latest_receipt_ids"][command] for command in commands if command in coverage.get("latest_receipt_ids", {})], "semantic_judgment": "not_machine_proven"}
            if plan.get("example"):
                executions = []
                for binding in plan.get("case_bindings", []):
                    command_id = binding["command_id"]
                    evidence = coverage.get("case_evidence_by_command", {}).get(command_id, {})
                    matches = [item for item in evidence.get("example_results", []) if item["example_ref"] == target]
                    matched = matches[0] if len(matches) == 1 else None
                    valid = bool(
                        evidence.get("status") == "recorded"
                        and evidence.get("freshness") != "stale"
                        and coverage.get("results", {}).get(command_id) == "passed"
                        and matched is not None
                        and matched.get("example_sha256") == plan["example"]["example_sha256"]
                        and [item["test_id"] for item in matched.get("tests", [])] == binding["test_ids"]
                        and matched.get("status") == "passed"
                    )
                    executions.append({"command_id": command_id, "command_result": coverage.get("results", {}).get(command_id, "not_run"), "report_status": evidence.get("status", "unavailable"), "status": "passed" if valid else "with_gaps", "tests": deepcopy(matched["tests"]) if matched else [{"test_id": identifier, "status": "not_run"} for identifier in binding["test_ids"]], "report_ref": evidence.get("report_ref"), "freshness": evidence.get("freshness", "unavailable")})
                executed = bool(executions) and all(item["status"] == "passed" for item in executions)
                review = submitted[target]
                row.update({
                    "status": "case_evidence_passed" if executed and review["outcome"] == "supported" else "case_evidence_incomplete",
                    "example": deepcopy(plan["example"]), "execution_results": executions,
                    "assertion_review": review, "semantic_judgment": "agent",
                })
                if row["status"] != "case_evidence_passed" and not limitations:
                    _fail("行为例子尚未验证或断言审阅未获支持，必须保留限制", details=target)
            rows.append(row)
        else:
            row = submitted[target]
            rows.append({**row, "method": plan["method"], "status": "agent_" + row["outcome"], "semantic_judgment": "agent", **({"example": deepcopy(plan["example"])} if plan.get("example") else {})})
    successful = {"command_evidence_passed", "case_evidence_passed", "agent_supported", "example_evidence_recorded"}
    by_ref = {row["target_ref"]: row for row in rows}
    for plan in plan_targets:
        if plan["method"] != "examples":
            continue
        children = plan["child_example_refs"]
        passed = all(child in by_ref and by_ref[child]["status"] in successful for child in children)
        rows.append({"target_ref": plan["target_ref"], "method": "examples", "status": "example_evidence_recorded" if passed else "example_evidence_incomplete", "child_example_refs": list(children), "semantic_judgment": "agent"})
    complete = all(row["status"] in successful for row in rows)
    return list(submitted.values()), {"schema_version": "strixnova.target-verification.v1", "status": "evidence_recorded" if complete else "with_gaps", "items": rows, "semantic_content_machine_proven": False}

strixnova/src/strixnova/work_item_relati.text:
"""Semantic trace relations between WorkItems.

The confirmed direction of the source WorkItem owns each relation fact.  This
module validates that small contract and derives bidirectional read views; it
does not create a second persistence, scheduling, or conflict authority.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from copy import deepcopy
from typing import Any
from strixnova.follow_ups import FollowUpError, normalize_ref, ref_key


WORK_ITEM_RELATION_SCHEMA = "strixnova.work-item-relation.v1"
WORK_ITEM_RELATION_TYPES = frozenset(
    {"related_to", "part_of", "depends_on", "follows_up", "supersedes"}
)


class WorkItemRelationError(ValueError):
    """A typed relation-contract failure for the Authority boundary."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


def _required_text(value: Any, field: str) -> str:
    if not isinstance(value, str):
        raise WorkItemRelationError(
            "work_item_relation_invalid",
            f"{field} 必须是字符串",
        )
    result = value.strip()
    if not result:
        raise WorkItemRelationError(
            "work_item_relation_invalid",
            f"{field} 不能为空",
        )
    return result


def normalize_work_item_relations(
    value: Any,
    *,
    source_work_item_id: str,
) -> list[dict[str, Any]]:
    """Validate and normalize the relations declared by one source WorkItem."""

    if not isinstance(value, list):
        raise WorkItemRelationError(
            "work_item_relation_invalid",
            "direction.work_item_relations 必须是数组",
        )
    source_id = _required_text(source_work_item_id, "source_work_item_id")
    required = {"target_work_item_id", "relation_type", "reason"}
    identities: set[tuple[str, str]] = set()
    normalized: list[dict[str, str]] = []
    for index, relation in enumerate(value):
        field = f"direction.work_item_relations[{index}]"
        if not isinstance(relation, Mapping):
            raise WorkItemRelationError(
                "work_item_relation_invalid",
                f"{field} 必须是对象",
            )
        missing = sorted(required - set(relation))
        extra = sorted(set(relation) - required - {"follow_up_refs"})
        if missing:
            raise WorkItemRelationError(
                "work_item_relation_invalid",
                f"{field} 缺少字段：" + ", ".join(missing),
            )
        if extra:
            raise WorkItemRelationError(
                "work_item_relation_invalid",
                f"{field} 包含未知字段：" + ", ".join(extra),
            )
        target_id = _required_text(
            relation.get("target_work_item_id"),
            f"{field}.target_work_item_id",
        )
        relation_type = _required_text(
            relation.get("relation_type"),
            f"{field}.relation_type",
        )
        reason = _required_text(relation.get("reason"), f"{field}.reason")
        if relation_type not in WORK_ITEM_RELATION_TYPES:
            raise WorkItemRelationError(
                "work_item_relation_type_invalid",
                f"{field}.relation_type 无效：{relation_type}",
            )
        if target_id == source_id:
            raise WorkItemRelationError(
                "work_item_relation_self_reference",
                "WorkItem 不能关联自身",
            )
        identity = (relation_type, target_id)
        if identity in identities:
            raise WorkItemRelationError(
                "work_item_relation_duplicate",
                (
                    "WorkItem 关系重复："
                    f"{relation_type}/{target_id}"
                ),
            )
        identities.add(identity)
        refs = relation.get("follow_up_refs", [])
        if not isinstance(refs, list) or (refs and relation_type != "follows_up"):
            raise WorkItemRelationError("follow_up_relation_invalid", "精确跟进引用只能用于 follows_up 关系")
        try:
            refs = [normalize_ref(ref) for ref in refs]
        except FollowUpError as error:
            raise WorkItemRelationError(error.code, str(error)) from error
        if any(ref["work_item_id"] != target_id for ref in refs) or len({ref_key(ref) for ref in refs}) != len(refs):
            raise WorkItemRelationError("follow_up_relation_invalid", "跟进引用必须唯一指向关系目标事项")
        normalized.append(
            {
                "target_work_item_id": target_id,
                "relation_type": relation_type,
                "reason": reason,
                **({"follow_up_refs": refs} if refs else {}),
            }
        )
    return normalized


def relation_target_ids(relations: Sequence[Mapping[str, Any]]) -> list[str]:
    """Return distinct target IDs in declaration order."""

    return list(
        dict.fromkeys(str(relation["target_work_item_id"]) for relation in relations)
    )


def build_work_item_relation_views(
    work_items: Sequence[Mapping[str, Any]],
) -> dict[str, dict[str, list[dict[str, Any]]]]:
    """Derive source-declared and target-referenced read views."""

    by_id = {str(item["work_item_id"]): item for item in work_items}
    views: dict[str, dict[str, list[dict[str, Any]]]] = {
        identifier: {"declared": [], "referenced_by": []}
        for identifier in by_id
    }
    for source_id, source in by_id.items():
        data = source.get("data")
        data = data if isinstance(data, Mapping) else {}
        confirmation = data.get("direction_confirmation")
        if not isinstance(confirmation, Mapping) or (
            confirmation.get("accepted") is not True
        ):
            continue
        direction = data.get("direction")
        direction = direction if isinstance(direction, Mapping) else {}
        raw_relations = direction.get("work_item_relations")
        if raw_relations is None:
            continue
        relations = normalize_work_item_relations(
            raw_relations,
            source_work_item_id=source_id,
        )
        for relation in relations:
            target_id = relation["target_work_item_id"]
            target = by_id.get(target_id)
            if target is None:
                continue
            edge = {
                "source_work_item_id": source_id,
                "target_work_item_id": target_id,
                "relation_type": relation["relation_type"],
                "reason": relation["reason"],
                **({"follow_up_refs": deepcopy(relation["follow_up_refs"])} if relation.get("follow_up_refs") else {}),
            }
            views[source_id]["declared"].append(
                {
                    **edge,
                    "related_work_item": _related_work_item(target),
                }
            )
            views[target_id]["referenced_by"].append(
                {
                    **edge,
                    "related_work_item": _related_work_item(source),
                }
            )
    for relation_view in views.values():
        relation_view["declared"].sort(key=_relation_sort_key)
        relation_view["referenced_by"].sort(key=_relation_sort_key)
    return views


def empty_work_item_relation_view() -> dict[str, list[dict[str, Any]]]:
    return {"declared": [], "referenced_by": []}


def _related_work_item(item: Mapping[str, Any]) -> dict[str, str]:
    return {
        "work_item_id": str(item["work_item_id"]),
        "title": str(item["title"]),
        "status": str(item["status"]),
    }


def _relation_sort_key(relation: Mapping[str, Any]) -> tuple[str, str, str]:
    return (
        str(relation["relation_type"]),
        str(relation["source_work_item_id"]),
        str(relation["target_work_item_id"]),
    )


__all__ = [
    "WORK_ITEM_RELATION_SCHEMA",
    "WORK_ITEM_RELATION_TYPES",
    "WorkItemRelationError",
    "build_work_item_relation_views",
    "empty_work_item_relation_view",
    "normalize_work_item_relations",
    "relation_target_ids",
]

strixnova/src/strixnova/work_item_reposi.text:
"""Repository responsibilities owned by the existing WorkItem aggregate."""

from __future__ import annotations

from collections.abc import Mapping
from copy import deepcopy
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Any


_UNSELECTED = object()
_selected_repository: ContextVar[Any] = ContextVar("strixnova_repository_operation", default=_UNSELECTED)


@contextmanager
def repository_operation(repository_id: str | None):
    """Select a repository for one application operation, never a second item."""
    token = _selected_repository.set(repository_id)
    try:
        yield
    finally:
        _selected_repository.reset(token)


def selected_repository(data: Mapping[str, Any], status: str) -> str | None:
    pending = data.get("pending_effect") or {}
    if "repository_id" in pending:
        return pending["repository_id"]
    selected = _selected_repository.get()
    if selected is not _UNSELECTED:
        return selected
    return ordered_repository(data, status)


def ordered_repository(data: Mapping[str, Any], status: str) -> str | None:
    """The aggregate's next repository, independent of a reader's selection."""
    entries = data.get("repository_deliveries") or []
    if status == "implementation_ready":
        entries = [entry for entry in entries if not (entry.get("git") or {}).get("work_ref")]
    else:
        entries = [entry for entry in entries if not (entry.get("git") or {}).get("cleanup", {}).get("safe")] or entries
    if entries:
        return entries[0]["repository_id"]
    return None


def repository_view(data: Mapping[str, Any], status: str, *, repository_id: Any = _UNSELECTED) -> dict[str, Any]:
    """Project the selected Git facts without persisting a duplicate singleton.

    Original snapshots without execution entries retain their recorded git value.
    This is also the only interpretation of old single-repository execution facts.
    """
    projected = deepcopy(dict(data))
    identifier = selected_repository(data, status) if repository_id is _UNSELECTED else repository_id
    entries = data.get("repository_deliveries") or []
    entry = next((entry for entry in entries if entry["repository_id"] == identifier), None)
    projected["selected_repository_id"] = identifier
    if entry is not None:
        projected["git"] = deepcopy(entry.get("git") or {})
        if not projected["git"] and len(entries) == 1 and "git" in data:
            projected["git"] = deepcopy(data["git"])
    elif entries:
        projected["git"] = {}
    return projected


def repository_item(current: Mapping[str, Any], repository_id: str | None) -> dict[str, Any]:
    result = deepcopy(dict(current))
    result["data"] = repository_view(current["data"], str(current["status"]), repository_id=repository_id)
    return result


def persist_repository_view(data: Mapping[str, Any]) -> dict[str, Any]:
    """Return one canonical representation for the next recorded snapshot."""
    result = deepcopy(dict(data))
    identifier = result.pop("selected_repository_id", None)
    entries = result.get("repository_deliveries") or []
    if not entries and (result.get("git") or {}).get("work_ref"):
        plan = (result.get("engineering") or {}).get("plan") or {}
        git = result["git"]
        if plan.get("plan_id"):
            entries = [{
                "schema_version": "strixnova.repository-delivery-responsibility.v1",
                "repository_id": identifier,
                "plan_id": plan["plan_id"],
                "investigation_commit": git.get("base_commit"),
                "target_ref": git.get("target_ref"),
                "operation_refs": [f"operations[{index}]" for index, _ in enumerate(plan.get("operations") or [])],
                "implementation_slice_ids": [entry["slice_id"] for entry in plan.get("implementation_slices") or []],
            }]
            result["repository_deliveries"] = entries
    if entries:
        git = result.pop("git", {})
        entry = next((entry for entry in entries if entry["repository_id"] == identifier), None)
        if entry is not None and git:
            entry["git"] = git
    return result


def repository_phase(entry: Mapping[str, Any]) -> str:
    git = entry.get("git") or {}
    if (git.get("cleanup") or {}).get("safe") is True:
        return "completed"
    integration = git.get("integration") or {}
    if integration.get("outcome") == "conflict" or git.get("conflict_resolution"):
        if not integration.get("integrated_commit"):
            return "integration_conflict"
    if integration.get("integrated_commit"):
        return "cleanup_required"
    if git.get("result_commits"):
        return "integration_required"
    return "commit_required" if git.get("work_ref") else "implementation_ready"


def previous_integrations(data: Mapping[str, Any]) -> list[dict[str, Any]]:
    """Project prior completed contributions without reopening their execution."""
    records = {}
    for delivery in data.get("superseded_deliveries") or []:
        for entry in delivery.get("repository_deliveries") or []:
            integration = (entry.get("git") or {}).get("integration") or {}
            commit = integration.get("integrated_commit")
            if commit:
                records[(entry["repository_id"], commit)] = {"repository_id": entry["repository_id"], "plan_id": entry["plan_id"], "integration": deepcopy(integration)}
    return list(records.values())


def planned_repository_deliveries(plan: Mapping[str, Any]) -> list[dict[str, Any]]:
    scope = plan.get("repository_scope")
    if not isinstance(scope, Mapping):
        # Original recorded plans did not contain repository identities.
        return []
    operations = list(plan.get("operations") or [])
    deliveries = []
    for entry in scope["repositories"]:
        if entry["role"] != "modify":
            continue
        identifier = entry["repository_id"]
        references = [
            f"operations[{index}]" for index, operation in enumerate(operations)
            if operation.get("repository_id") == identifier
        ]
        if not references:
            continue
        slices = [
            item["slice_id"] for item in plan.get("implementation_slices") or []
            if set(references).intersection([*item["operation_refs"], *item.get("continued_operation_refs", [])])
        ]
        deliveries.append({
            "schema_version": "strixnova.repository-delivery-responsibility.v1",
            "repository_id": identifier,
            "plan_id": plan["plan_id"],
            "investigation_commit": None if entry["investigation_ref"] == "working_tree" else entry["investigation_ref"],
            "target_ref": entry["target_ref"],
            "operation_refs": references,
            "implementation_slice_ids": slices,
        })
    order = (plan.get("delivery_plan") or {}).get("repository_order") or []
    return sorted(deliveries, key=lambda entry: order.index(entry["repository_id"]) if entry["repository_id"] in order else len(order))


def repository_responsibility_view(item: Mapping[str, Any]) -> dict[str, Any]:
    data = item.get("data") or {}
    plan = (data.get("engineering") or {}).get("plan") or {}
    responsibilities = deepcopy(data.get("repository_deliveries") or [])
    return {
        "schema_version": "strixnova.repository-delivery-responsibility-view.v1",
        "project_id": data.get("project_id"),
        "work_item_id": item["work_item_id"],
        "work_item_version": item["version"],
        "current_plan_id": plan.get("plan_id"),
        "responsibilities": [
            {**entry, "current_plan": entry["plan_id"] == plan.get("plan_id")}
            for entry in responsibilities
        ],
        "scope": "repository_responsibilities_and_execution",
        "execution_facts_included": True,
        "overall_result_confirmation": deepcopy(data.get("actual_result_confirmation")),
    }

