        known_fingerprints = {
            str(item["confirmation"].get("candidate_fingerprint") or "")
            for item in decisions
            if isinstance(item, Mapping)
            and isinstance(item.get("confirmation"), Mapping)
        }
        rejected: list[str] = []
        for index, raw_record in enumerate(raw_records):
            record = _object(
                raw_record,
